619	function handleTransferProgress(msg) {
620	    // 接收方：更新文件消息进度
621	    const result = findFileMsgByTransferId(msg.transfer_id);
622	    if (result && msg.total_bytes > 0) {
623	        result.msg.progress = Math.round(msg.received_bytes / msg.total_bytes * 100);
624	        if (currentChat) renderMessages(currentChat);
625	    }
626	}
