628	function handleTransferComplete(msg) {
629	    // 接收方：传输完成
630	    const result = findFileMsgByTransferId(msg.transfer_id);
631	    if (result) {
632	        const { msg: fileMsg, peerUuid } = result;
633	        fileMsg.status = msg.verified ? 'complete' : 'failed';
634	        fileMsg.progress = 100;
635	        saveFileMessage(peerUuid, fileMsg);
636	        if (currentChat === peerUuid) renderMessages(currentChat);
637	    }
638	    if (msg.verified) {
639	        showToast(`文件接收完成: ${msg.file_name}`);
640	    } else {
