645	function handleTransferCancelled(msg) {
646	    const result = findFileMsgByTransferId(msg.transfer_id);
647	    if (result) {
648	        const { msg: fileMsg, peerUuid } = result;
649	        fileMsg.status = 'cancelled';
650	        saveFileMessage(peerUuid, fileMsg);
651	        if (currentChat === peerUuid) renderMessages(currentChat);
652	    }
653	    // 清理上传方状态
654	    if (pendingFileTransfers[msg.transfer_id]) {
655	        delete pendingFileTransfers[msg.transfer_id];
656	    }
657	    showToast('文件传输已取消');
658	}
