1892	async function startChunkUpload(transferId) {
1893	    const t = pendingFileTransfers[transferId];
1894	    if (!t) return;
1895	
1896	    const result = findFileMsgByTransferId(transferId);
1897	    const fileMsg = result ? result.msg : null;
1898	    if (result) {
1899	        fileMsg.status = 'uploading';
1900	        saveFileMessage(t.uuid, fileMsg);
1901	        if (currentChat === t.uuid) renderMessages(t.uuid);
1902	    }
1903	
1904	    const peer = getPeerEndpoint(t.uuid);
1905	    if (!peer || !peer.ip) {
1906	        showToast('缺少对方地址信息，无法发送文件');
1907	        if (fileMsg) {
1908	            fileMsg.status = 'failed';
1909	            saveFileMessage(t.uuid, fileMsg);
1910	            if (currentChat === t.uuid) renderMessages(t.uuid);
1911	        }
1912	        delete pendingFileTransfers[transferId];
1913	        return;
1914	    }
1915	
1916	    const file = t.file;
1917	    const CHUNK_SIZE = t.CHUNK_SIZE;
1918	    const totalChunks = t.totalChunks;
1919	    const peerPort = peer.ws_port || 50002;
1920	
1921	    for (let i = t.currentChunk; i < totalChunks; i++) {
1922	        // 检查连接是否被中断（断开连接 / 对方下线）
1923	        if (t.aborted) {
1924	            if (fileMsg) {
1925	                fileMsg.status = 'cancelled';
1926	                saveFileMessage(t.uuid, fileMsg);
1927	                if (currentChat === t.uuid) renderMessages(t.uuid);
1928	            }
1929	            return; // 连接中断，中止上传
1930	        }
1931	
1932	        const start = i * CHUNK_SIZE;
1933	        const end = Math.min(start + CHUNK_SIZE, file.size);
1934	        const blob = file.slice(start, end);
1935	
1936	        let dataB64;
1937	        try {
1938	            dataB64 = await readAsBase64(blob);
1939	        } catch (e) {
1940	            // 文件读取失败（权限变更、文件被删、磁盘错误等），不可恢复
1941	            t.failed = true;
1942	            if (fileMsg) {
1943	                fileMsg.status = 'failed';
1944	                saveFileMessage(t.uuid, fileMsg);
1945	                if (currentChat === t.uuid) renderMessages(t.uuid);
1946	            }
1947	            return;
1948	        }
1949	
1950	        let retries = 0;
1951	        let success = false;
1952	
1953	        while (retries < 3 && !success) {
1954	            if (t.aborted) {
1955	                if (fileMsg) {
1956	                    fileMsg.status = 'cancelled';
1957	                    saveFileMessage(t.uuid, fileMsg);
1958	                    if (currentChat === t.uuid) renderMessages(t.uuid);
1959	                }
1960	                return;
1961	            }
1962	            try {
1963	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1964	                    method: 'POST',
1965	                    headers: { 'Content-Type': 'application/json' },
1966	                    body: JSON.stringify({
1967	                        transfer_id: transferId,
1968	                        chunk_index: i,
1969	                        data: dataB64,
1970	                    }),
1971	                });
1972	                if (resp.ok) {
1973	                    success = true;
1974	                    t.currentChunk = i + 1;
1975	                    // 更新进度条（取消后不再刷新为发送中）
1976	                    if (fileMsg && !t.aborted) {
1977	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1978	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1979	                    }
1980	                } else {
1981	                    retries++;
1982	                }
1983	            } catch (e) {
1984	                retries++;
1985	            }
1986	        }
1987	
1988	        if (!success) {
1989	            t.failed = true;
1990	            if (fileMsg) {
1991	                fileMsg.status = 'failed';
1992	                saveFileMessage(t.uuid, fileMsg);
1993	                if (currentChat === t.uuid) renderMessages(t.uuid);
1994	            }
1995	            return; // 传输中断（保留 t 以便续传）
1996	        }
1997	    }
1998	
1999	    // 所有分片发送完毕 → 通知对方合并
2000	    try {
2001	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
2002	            method: 'POST',
2003	            headers: { 'Content-Type': 'application/json' },
2004	            body: JSON.stringify({ transfer_id: transferId }),
2005	        });
2006	        if (fileMsg) {
2007	            fileMsg.status = 'complete';
2008	            fileMsg.progress = 100;
2009	            saveFileMessage(t.uuid, fileMsg);
2010	            if (currentChat === t.uuid) renderMessages(t.uuid);
2011	        }
2012	    } catch (e) {
2013	        if (fileMsg) {
2014	            fileMsg.status = 'failed';
2015	            saveFileMessage(t.uuid, fileMsg);
2016	            if (currentChat === t.uuid) renderMessages(t.uuid);
2017	        }
2018	    }
2019	
2020	    delete pendingFileTransfers[transferId];
2021	}
