2107	    const ws = activeChats.get(t.uuid);
2108	    if (ws && ws.readyState === WebSocket.OPEN) {
2109	        ws.send(JSON.stringify({ type: 'file_request', ...fileRequestMsg }));
2110	    } else {
2111	        // 回退路径：通过 control WS 转发
2112	        controlWs.send(JSON.stringify({
2113	            type: 'file_request',
2114	            to_uuid: t.uuid,
2115	            ...fileRequestMsg,
2116	        }));
