2120	function readAsBase64(blob) {
2121	    return new Promise((resolve, reject) => {
2122	        const reader = new FileReader();
2123	        reader.onloadend = () => {
2124	            const result = reader.result;
2125	            // 去掉 "data:...;base64," 前缀
2126	            const b64 = result.split(',')[1] || result;
2127	            resolve(b64);
2128	        };
2129	        reader.onerror = () => {
2130	            reject(new Error('文件读取失败'));
2131	        };
2132	        reader.readAsDataURL(blob);
2133	    });
2134	}
